const touch={enabled:typeof matchMedia==='function'&&matchMedia('(pointer: coarse)').matches,pointer:null,x:0,y:0,zoom:false,originX:0,originY:0};
function resetStick(){touch.pointer=null;touch.x=0;touch.y=0;$('touch-knob').style.transform='translate(0px,0px)'}
function clearControls(){keys.clear();resetStick()}
function controlText(text){return touch.enabled?text.replace(/pulsa E/gi,'pulsa Entregar').replace(/pulsa Q/gi,'pulsa Soltar').replace(/WASD o flechas/g,'el joystick'):text}
function syncTouchUI(){document.documentElement?.classList.toggle('touch-mode',touch.enabled);$('touch-toggle').textContent=touch.enabled?'Usar solo teclado':'Activar controles táctiles';$('touch-toggle').setAttribute('aria-pressed',String(touch.enabled));$('touch-map').setAttribute('aria-pressed',String(touch.zoom));$('touch-map').textContent=touch.zoom?'Ver mapa':'Ampliar';clearControls()}
function moveStick(e){if(e.pointerId!==touch.pointer)return;const dx=e.clientX-touch.originX,dy=e.clientY-touch.originY,d=Math.hypot(dx,dy),r=38,m=Math.min(d,r),force=d<8?0:(m-8)/(r-8);touch.x=d?dx/d*force:0;touch.y=d?dy/d*force:0;$('touch-knob').style.transform=`translate(${d?dx/d*m:0}px,${d?dy/d*m:0}px)`}
function beginStick(e){if(!touch.enabled||!active()||touch.pointer!==null)return;e.preventDefault();const r=$('touch-stick').getBoundingClientRect();touch.pointer=e.pointerId;touch.originX=r.left+r.width/2;touch.originY=r.top+r.height/2;$('touch-stick').setPointerCapture(e.pointerId);moveStick(e)}
function endStick(e){if(e.pointerId===touch.pointer)resetStick()}
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),rand=(a,b)=>a+Math.random()*(b-a);
function level(){return levels[s.level]}function task(){return level().steps.find(t=>s.progressBy[t.station]<t.target)||level().steps[0]}
function active(){return running&&!paused&&!s.waiting&&!uiAudioOpen&&!uiHelpOpen&&!uiCourseOpen&&!uiMissionsOpen}
const audio={effects:.55,music:.18,musicEnabled:true,nextBeat:0,beat:0,fxBus:null,musicBus:null,master:null};
function initAudio(){try{if(!ac){ac=new(window.AudioContext||window.webkitAudioContext)();audio.master=ac.createGain();audio.fxBus=ac.createGain();audio.musicBus=ac.createGain();audio.master.connect(ac.destination);audio.fxBus.connect(audio.master);audio.musicBus.connect(audio.master);audio.nextBeat=ac.currentTime;syncAudio()}ac.resume().catch(()=>{});}catch{}}
function syncAudio(){if(!ac)return;const now=ac.currentTime;audio.master.gain.setTargetAtTime(sound?1:0,now,.04);audio.fxBus.gain.setTargetAtTime(audio.effects,now,.03);audio.musicBus.gain.setTargetAtTime(audio.musicEnabled&&running&&!paused&&!s.waiting&&!uiHelpOpen&&!uiMissionsOpen?audio.music:0,now,.12)}
function note(freq,when,duration,volume=.12,type='sine',bus=audio.fxBus,endFreq){if(!ac||!bus)return;const o=ac.createOscillator(),g=ac.createGain();o.type=type;o.frequency.setValueAtTime(freq,when);if(endFreq)o.frequency.exponentialRampToValueAtTime(endFreq,when+duration);o.connect(g);g.connect(bus);g.gain.setValueAtTime(.0001,when);g.gain.exponentialRampToValueAtTime(Math.max(.0002,volume),when+Math.min(.03,duration/5));g.gain.exponentialRampToValueAtTime(.0001,when+duration);o.start(when);o.stop(when+duration+.02);o.onended=()=>{o.disconnect();g.disconnect()}}
function fx(kind){if(!sound||!ac)return;const t=ac.currentTime;const patterns={pickup:[660,990],deposit:[350,525],success:[523,659,784],level:[523,659,784,1047],error:[180,130],drop:[380,240],start:[392,523,659]};if(kind==='dash'){note(180,t,.36,.13,'triangle',audio.fxBus,1200);note(100,t,.4,.08,'sine',audio.fxBus,55);return}const notes=patterns[kind]||patterns.deposit;notes.forEach((f,i)=>note(f,t+i*.075,kind==='level'?.5:.2,kind==='pickup'?.065:.11,kind==='error'?'triangle':'sine'))}
function musicTick(){if(!ac||!running||paused||s.waiting||uiHelpOpen||uiMissionsOpen||!sound||!audio.musicEnabled){if(ac)audio.nextBeat=ac.currentTime;return}const now=ac.currentTime;if(audio.nextBeat<now-.2)audio.nextBeat=now;const chords=[[130.81,164.81,196],[110,130.81,164.81],[87.31,130.81,174.61],[98,146.83,196]];while(audio.nextBeat<now+.12){const chord=chords[Math.floor(audio.beat/8)%4],t=audio.nextBeat;if(audio.beat%8===0)chord.forEach(f=>note(f,t,4.5,.08,'sine',audio.musicBus));if(audio.beat%2===0)note(chord[(audio.beat/2)%3]*2,t,1.4,.07,'sine',audio.musicBus);audio.nextBeat+=.65;audio.beat++}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2200)}
const bacteriaShape={left:287,right:713,cy:320,r:211};
function membraneDistance(point){if(s.level===1){const dx=Math.abs(point.x-500)-348,dy=Math.abs(point.y-321)-188;return 85-Math.hypot(Math.max(dx,0),Math.max(dy,0))-Math.min(Math.max(dx,dy),0)}if(s.level!==2)return (1-Math.hypot((point.x-500)/443,(point.y-320)/286))*286;const b=bacteriaShape,cx=Math.max(b.left,Math.min(b.right,point.x));return b.r-Math.hypot(point.x-cx,point.y-b.cy)}
function nearStation(){if(level().stations.includes('membrane')&&membraneDistance(s.player)<=43)return 'membrane';return level().stations.filter(k=>!['membrane','cytoplasm'].includes(k)).map(k=>({key:k,d:distance(s.player,structures[k]),limit:structures[k].r+24})).filter(v=>v.d<v.limit).sort((a,b)=>a.d-b.d)[0]?.key||null}
function emissionPoint(key,index=0){const points={rer:{x:565,y:135},rel:{x:297,y:343},chloro:{x:365,y:455}};const p=points[key]||{x:structures[key].x+80,y:structures[key].y};return {x:p.x,y:p.y+index*32}}
function spawn(type,position){let p;for(let i=0;i<500;i++){p=position||{x:rand(130,870),y:rand(115,515)};if(position||Math.hypot((p.x-500)/365,(p.y-320)/228)<1&&!level().stations.some(k=>k!=='membrane'&&distance(p,structures[k])<structures[k].r+22)&&distance(p,{x:480,y:290})>112&&!s.items.some(a=>distance(a,p)<33))break;}s.items.push({...p,type,phase:rand(0,6.28),lock:position?1.1:0})}
function initFlight(){s.player={x:490,y:470,vx:0,vy:0,angle:-Math.PI/2};s.cargo=[];s.items=[];s.trail=[];s.particles=[];s.shipments=[];s.deposit={};s.progressBy=Object.fromEntries(level().steps.map(t=>[t.station,0]));s.hinted={};s.dash=0;s.boost=0;s.elapsed=0;s.near=null;s.magnet=0;for(const type of level().pool){const count=['info','react'].includes(type)?1:isBasic()?level().steps.filter(t=>t.recipe[0]===type).length:['p','l'].includes(type)||s.level===1&&['g','o'].includes(type)?0:type==='a'||type==='w'?3:2;for(let i=0;i<count;i++)spawn(type)}}
function reset(){closeMissionHelp();s={level:selectedCell,energy:0,score:0,health:3,streak:0,correct:0,errors:0,hints:0,actions:0,totalActions:0,completed:0,waiting:false,feedback:isBasic()?'Recoge encargos y pulsa E junto a la estructura que realiza esa función.':'Pilota con WASD o flechas. Recoge moléculas y pulsa E junto a su destino.'};initFlight();render()}
function start(){running=true;paused=false;clearControls();reset();['intro','end','paused','level-end'].forEach(id=>$(id).classList.add('hidden'));canvas.focus();initAudio();syncAudio();fx('start')}
function burst(x,y,color,text){for(let i=0;i<20;i++){const a=rand(0,Math.PI*2),v=rand(30,140);s.particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:1,color})}if(text)s.particles.push({x,y:y-55,vx:0,vy:-28,life:1.8,color,text})}
function drop(){if(!active()||!s.cargo.length)return;const type=s.cargo.pop();spawn(type,{x:s.player.x,y:s.player.y});render();fx('drop')}
function dash(){if(!active()||s.dash>0)return;s.dash=3;s.boost=.4;s.magnet=1.2;const p=s.player;if(Math.hypot(p.vx,p.vy)<10){p.vx=Math.cos(p.angle)*200;p.vy=Math.sin(p.angle)*200}fx('dash')}
function transfer(){if(!active())return;const dest=nearStation();if(!dest){toast('Acércate a una estructura para entregar con E.');return}deliver(dest)}
function processReady(){const messages=[];let changed=true;while(changed){changed=false;for(const t of level().steps){const deposit=s.deposit[t.station]||{};if(s.progressBy[t.station]>=t.target||!t.recipe.every(k=>deposit[k]>0)||s.energy<energyCost(t))continue;for(const k of t.recipe)deposit[k]--;if(t.kind==='energy')s.energy+=20;s.energy-=energyCost(t);const st=['membrane','cytoplasm'].includes(t.station)?s.player:structures[t.station];if(t.kind==='photo'){spawn('g',emissionPoint(t.station));spawn('o',emissionPoint(t.station,1))}if(t.output)spawn(t.output,emissionPoint(t.station));if(t.kind==='sorting')s.shipments.push({x:st.x,y:st.y,life:3});s.progressBy[t.station]++;s.correct++;s.actions++;s.totalActions++;const helped=!!s.hinted[t.station];s.streak=helped?0:s.streak+1;const mult=1+Math.min(3,Math.floor(Math.max(0,s.streak-1)/2)),points=helped?40:100*mult;s.score+=points;delete s.hinted[t.station];messages.push(t.result+` +${points} puntos.`);burst(st.x,st.y,'#d7ff80','+'+points+' · '+(t.kind==='energy'?'20 ATP':t.kind==='photo'?'Glucosa + O₂':t.kind==='protein'?'Proteína':'Objetivo'));changed=true}}
if(messages.length){s.feedback=messages.join(' ');fx('success')}
if(level().steps.every(t=>s.progressBy[t.station]>=t.target)){s.completed++;s.score+=200;s.waiting=true;clearControls();showLevelEnd();fx('level');syncAudio()}
return messages.length}
function deliver(destination){if(!active())return;const t=level().steps.find(t=>t.station===destination),st=['membrane','cytoplasm'].includes(destination)?s.player:structures[destination];if(!t)return;if(s.progressBy[destination]>=t.target){toast('Objetivo completo. Coordina los otros procesos para avanzar.');return}if(!s.cargo.length){toast(isBasic()?'Recoge un encargo y llévalo a su destino.':'Recoge moléculas. Las entregadas ya esperan en el orgánulo.');return}
const useful=s.cargo.filter(k=>t.recipe.includes(k));if(!useful.length){s.errors++;s.health--;s.streak=0;s.feedback=(isBasic()?'Este encargo no corresponde a la función de ':'Esta carga no sirve en ')+structures[destination].name.toLowerCase()+'. Conservas los materiales: prueba otro destino o pulsa Q para soltar.';burst(st.x,st.y,'#ff8c9e','Revisa los materiales');fx('error');render();if(!s.health)finish(false);return}
const deposit=s.deposit[destination]??={};let moved=0;for(let i=s.cargo.length-1;i>=0;i--){const k=s.cargo[i];if(t.recipe.includes(k)&&(deposit[k]||0)<t.target-s.progressBy[destination]){deposit[k]=(deposit[k]||0)+1;s.cargo.splice(i,1);moved++}}
if(!processReady()){const missing=t.recipe.filter(k=>!deposit[k]).map(k=>materials[k].name);s.feedback=missing.length?'Material guardado. Falta '+missing.join(' + ')+'. Puedes atender otro proceso mientras tanto.':s.energy<energyCost(t)?'Materiales en espera: faltan '+energyCost(t)+' ATP. Al producir energía, el proceso comenzará automáticamente.':'Ya hay suficiente de ese material en espera. Conservas el resto de la carga.';if(moved)fx('deposit')}render()}
function canReadHint(){return running&&!paused&&!s.waiting&&!uiAudioOpen&&!uiHelpOpen&&!uiCourseOpen}
function hint(destination){if(!canReadHint())return;closeMissionHelp();const t=level().steps.find(t=>t.station===destination)||level().steps.find(t=>t.station===s.near&&s.progressBy[t.station]<t.target)||task();if(s.progressBy[t.station]>=t.target){toast('Ese objetivo ya está completo.');return}if(!s.hinted[t.station]){s.hints++;s.hinted[t.station]=true}s.feedback=t.hint.replace('Envía','Lleva').replace('Combina','Recoge')+' Pulsa E cerca del destino. Su próximo proceso dará 40 puntos.';render();$('hint-title').textContent=t.label||goalNames[t.kind];$('hint-copy').textContent=controlText(t.hint);uiHelpOpen=true;clearControls();syncAudio();$('hint-dialog').showModal()}
function showLevelEnd(){$('level-end').classList.remove('hidden');$('level-result-title').textContent=level().short+' completada';$('level-result-copy').textContent=level().fact;$('level-result-stats').textContent=`${s.correct} procesos correctos · ${s.score} puntos`;$('next-level').textContent='Ver mi resultado →';$('bank').classList.add('hidden')}
function nextLevel(){if(s.waiting)finish(true)}
function finish(won){running=false;syncAudio();s.waiting=false;clearControls();$('level-end').classList.add('hidden');$('end').classList.remove('hidden');$('end-label').textContent=won?'EXPEDICIÓN COMPLETADA':'CADA INTENTO TE ENSEÑA ALGO';$('end-title').textContent=won?'¡La vida sigue!':'Vuelve a intentarlo';$('end-copy').textContent=`${level().name} · ${s.completed?'completada':'en práctica'}. `+(won?'Tu conocimiento ha abierto el camino.':'Piensa en la función del orgánulo antes de entregar.');$('result-score').textContent=s.score.toLocaleString('es')+' pts';$('results').textContent=`${s.correct} procesos · ${s.errors} errores · ${s.hints} pistas`;if(s.score>best){best=s.score;$('best').textContent=best;try{localStorage.setItem(bestKey(),best)}catch{}$('end-label').textContent='✦ NUEVO RÉCORD PERSONAL'}}
function togglePause(){if(!running||s.waiting)return;paused=!paused;syncAudio();clearControls();$('paused').classList.toggle('hidden',!paused);if(!paused)canvas.focus()}
function renderFlightStatus(){
 const dest=nearStation(),t=level().steps.find(t=>t.station===dest);
 const target=dest?structures[dest].name:'ELIGE UN DESTINO';
 let action='Acércate a una estructura con tu carga';
 if(dest){
   if(s.progressBy[dest]>=t.target)action='Objetivo completado · busca otro destino';
   else if(!s.cargo.length)action='Primero recoge una ficha';
   else action=touch.enabled?'Pulsa Entregar para entregar aquí':'<kbd>E</kbd> Entregar tu carga aquí';
 }
 const markup='<span class="destination-caption">'+(dest?'DESTINO CERCANO':'EXPLORA LA CÉLULA')+'</span><strong>'+(dest?target:'Recoge y transporta')+'</strong><span class="destination-action">'+action+'</span>';
 if($('flight-status').innerHTML!==markup)$('flight-status').innerHTML=markup;
 $('flight-status').classList.toggle('has-destination',!!dest);
 for(const id of ['touch-deliver','touch-dash','touch-drop'])$(id).disabled=!active()||(id==='touch-dash'&&s.dash>0);
 $('touch-dash').textContent=s.dash>0?'Impulso '+s.dash.toFixed(1)+' s':'Impulso';
}
function render(){const l=level();$('light-status').hidden=s.level!==1;$('cell-label').textContent=l.name.toUpperCase();$('energy-label').textContent=isBasic()?'FUNCIONES RESUELTAS':'ENERGÍA · ATP';$('energy').textContent=isBasic()?s.correct:s.energy;$('score').textContent=String(s.score).padStart(4,'0');$('time').textContent=Object.values(s.progressBy).filter((v,i)=>v>=l.steps[i].target).length+' / '+l.steps.length;$('missions-open').textContent='Misiones · '+$('time').textContent;$('health-bar').style.width=s.health/3*100+'%';$('health-text').textContent=s.health+' oportunidades';$('phase').textContent=l.steps.length+' MISIONES';$('mission-title').textContent=isBasic()?'Activa sus funciones':'Conecta sus procesos';$('mission-copy').textContent=isBasic()?'Relaciona cada encargo con su estructura. Tú eliges el orden.':s.level===2?'Lleva glucosa y oxígeno a cualquier tramo de la membrana. Los ribosomas pueden esperar el ATP.':'Coordina los procesos: RER → proteína P, REL → lípido L, y ambos → Golgi. Una operación por objetivo; puedes combinarlos.';
$('course-value').textContent=courseName();$('start').setAttribute('aria-label','Empezar partida: '+l.name);$('course-label').textContent=courseName()+' · '+l.short;$('intro-copy').textContent=isBasic()?'Pilota por el citoplasma. Recoge encargos y encuentra la estructura que realiza cada función.':'Pilota por el citoplasma. Recoge moléculas y coordina los procesos de la célula.';$('mode-description').textContent=isBasic()?'Reconocer estructuras y relacionarlas con su función.':'Relacionar estructuras, materiales y procesos interdependientes.';
$('guide-open').textContent=isBasic()?'Ver encargos y funciones ↗':'Ver moléculas y funciones ↗';$('materials-title').textContent=isBasic()?'Reconoce los encargos':'Reconoce las moléculas';$('materials-help').textContent=isBasic()?'Estas fichas son encargos simbólicos, no moléculas reales. Recógelas y pulsa E en la estructura adecuada. PR representa fabricar proteínas; consulta qué estructuras participan en tu célula.':'Recoge moléculas y lleva los materiales a su destino. Los materiales entregados esperan en la estructura. Puedes llevar tres a la vez; Q suelta la última.'+(s.level===2?' ADN es un encargo simbólico para localizar la información genética; no representa una molécula transportada.':'');
$('goals').classList.toggle('basic-goals',isBasic());$('guide-basic').hidden=!isBasic();$('guide-advanced').hidden=isBasic();$('teacher-basic').hidden=!isBasic();$('teacher-advanced').hidden=isBasic();

$('goals').innerHTML=l.steps.map(t=>{const done=s.progressBy[t.station]>=t.target;return `<div class="goal ${done?'done':''}"><span class="goal-symbol" style="color:${materials[t.recipe[0]].color}">${done?'✓':isBasic()?materials[t.recipe[0]].symbol:'◇'}</span><span>${t.label||goalNames[t.kind]}${s.hinted[t.station]?'<small>Pista revelada · 40 pts</small>':''}</span>${t.target>1?`<b>${s.progressBy[t.station]} / ${t.target}</b>`:''}<button data-help="${t.station}" aria-label="Ayuda: ${t.title}" aria-describedby="mission-help">?</button></div>`}).join('');$('feedback').textContent=controlText(s.feedback);$('combo').textContent=`Racha ${s.streak} · Próximo proceso ×${1+Math.min(3,Math.floor(s.streak/2))}`;$('level-track').innerHTML=levels.map((v,i)=>`<button data-cell="${i}" aria-pressed="${i===s.level}" title="Jugar con célula ${v.short.toLowerCase()}: inicia una nueva partida" class="${i===s.level?'active':''}">${v.short}</button>`).join('');$('materials').innerHTML=l.pool.map(k=>`<span style="--cargo:${materials[k].color}"><b>${materials[k].symbol}</b>${materials[k].name}</span>`).join('');$('hint').disabled=!canReadHint();$('hint').textContent=touch.enabled?'Revelar una pista':'H · Revelar una pista';$('level-fact').textContent=l.fact;renderFlightStatus()}
function update(dt){if(!active()){if(touch.enabled)renderFlightStatus();return;}s.elapsed+=dt;s.dash=Math.max(0,s.dash-dt);s.boost=Math.max(0,s.boost-dt);s.magnet=Math.max(0,(s.magnet||0)-dt);const p=s.player;let dx=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft')),dy=Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'));if(touch.enabled){dx+=touch.x;dy+=touch.y}const length=Math.hypot(dx,dy);if(length){if(length>1){dx/=length;dy/=length}p.angle=Math.atan2(dy,dx)}const speed=s.boost>0?690:245,blend=1-Math.exp(-14*dt);const bx=s.boost>0&&!length?Math.cos(p.angle):dx,by=s.boost>0&&!length?Math.sin(p.angle):dy;p.vx+=(bx*speed-p.vx)*blend;p.vy+=(by*speed-p.vy)*blend;p.x+=p.vx*dt;p.y+=p.vy*dt;if(s.level===2){const b=bacteriaShape,cx=Math.max(b.left,Math.min(b.right,p.x)),dx=p.x-cx,dy=p.y-b.cy,d=Math.hypot(dx,dy),limit=b.r-16;if(d>limit){p.x=cx+dx/d*limit;p.y=b.cy+dy/d*limit;p.vx*=.25;p.vy*=.25}}else if(s.level===1){const cx=Math.max(152,Math.min(848,p.x)),cy=Math.max(133,Math.min(509,p.y)),dx=p.x-cx,dy=p.y-cy,d=Math.hypot(dx,dy);if(d>69){p.x=cx+dx/d*69;p.y=cy+dy/d*69;p.vx*=.25;p.vy*=.25}}else{let nx=(p.x-500)/411,ny=(p.y-320)/258,n=Math.hypot(nx,ny);if(n>1){p.x=500+nx/n*411;p.y=320+ny/n*258;p.vx*=.25;p.vy*=.25}}if(s.level!==2){const centre={x:480,y:285},d=distance(p,centre);if(d<90){const a=d?Math.atan2(p.y-centre.y,p.x-centre.x):0;p.x=centre.x+Math.cos(a)*90;p.y=centre.y+Math.sin(a)*90}}
if(Math.hypot(p.vx,p.vy)>20)s.trail.push({x:p.x,y:p.y,life:.35});for(const tr of s.trail)tr.life-=dt;s.trail=s.trail.filter(tr=>tr.life>0);for(let i=s.items.length-1;i>=0;i--){const item=s.items[i];item.lock=Math.max(0,item.lock-dt);if(!item.lock&&s.magnet>0&&s.cargo.length<3&&distance(p,item)<105){const amount=Math.min(1,dt*9);item.x+=(p.x-item.x)*amount;item.y+=(p.y-item.y)*amount}if(!item.lock&&distance(p,item)<28&&s.cargo.length<3){s.cargo.push(item.type);s.items.splice(i,1);fx('pickup');render()}}
s.near=nearStation();for(const v of s.shipments){v.life-=dt;v.x+=dt*65;v.y-=dt*10}s.shipments=s.shipments.filter(v=>v.life>0);for(const particle of s.particles){particle.life-=dt;particle.x+=particle.vx*dt;particle.y+=particle.vy*dt}s.particles=s.particles.filter(a=>a.life>0);renderFlightStatus()}

function ellipse(x,y,rx,ry,fill,stroke,width=1){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke()}}
