function switchCourse(next){if(!['eso','bach'].includes(next)||next===course)return;course=next;levels=isBasic()?basicLevels:advancedLevels;best=readBest();$('best').textContent=best;try{localStorage.setItem('micro-course',course)}catch{}running=false;paused=false;clearControls();clearTimeout(toastTimer);$('toast').classList.remove('show');['end','paused','level-end'].forEach(id=>$(id).classList.add('hidden'));$('intro').classList.remove('hidden');reset();syncAudio()}
