let helpTarget=null,helpTimer;
const missionHelpText={mito:'La célula necesita energía para realizar sus funciones. Relaciona ese trabajo con la estructura que lo permite.',ribo:'Las proteínas son necesarias para construir y mantener la célula. Encuentra la estructura que las fabrica.',rer:'Una parte del retículo lleva pequeños ribosomas adheridos. Observa el dibujo para distinguirla de la parte lisa.',rel:'Los lípidos forman parte de las membranas. Busca la estructura especializada en fabricarlos.',golgi:'Fabricar y organizar un envío son trabajos distintos. Esta misión trata de preparar y distribuir materiales.',lyso:'Reciclar permite recuperar componentes de materiales que ya no son útiles.',chloro:'La célula de una hoja puede fabricar alimento aprovechando la luz. No confundas esta función con obtener energía del alimento.',vacuole:'Almacenar agua ayuda a mantener la célula vegetal. Busca una estructura amplia dentro de ella.',membrane:'La bacteria también intercambia sustancias con el entorno. El borde interior completo es una zona de entrega.',nucleoid:'Una bacteria tiene instrucciones genéticas, aunque no tiene un núcleo que las encierre.'};
function closeMissionHelp(){clearTimeout(helpTimer);if($('mission-help').matches?.(':popover-open'))$('mission-help').hidePopover();helpTarget=null}
function showMissionHelp(button){clearTimeout(helpTimer);helpTarget=button.dataset.help;const t=level().steps.find(t=>t.station===helpTarget);if(!t)return;$('mission-help-title').textContent=t.label||goalNames[t.kind];$('mission-help-copy').textContent=t.station==='membrane'&&!isBasic()?'Esta bacteria obtiene energía usando oxígeno, pero no tiene mitocondrias. Tendrás que encontrar otra estructura implicada en ese proceso.':missionHelpText[t.station];$('mission-reveal').disabled=!canReadHint()||s.progressBy[t.station]>=t.target;$('mission-help').showPopover();placePopover($('mission-help'),button)}
const deferHelpClose=()=>{helpTimer=setTimeout(closeMissionHelp,200)};
