$('goals').addEventListener('pointerout',e=>{if(e.target.closest('[data-help]'))deferHelpClose()});
$('goals').addEventListener('focusin',e=>{const b=e.target.closest('[data-help]');if(b)showMissionHelp(b)});
$('goals').addEventListener('focusout',deferHelpClose);
